    asm volatile(
        "tcgen05.ld.sync.aligned.32x1b.x4.b32 {%0, %1, %2, %3}, [%4];"
        : "=f"(result.x), "=f"(result.y),
          "=f"(result.z), "=f"(result.w)
        : "r"(tmem_col)
    );
    return result;
}
