__global__ void hopper_kernel(/* ... */) {
    // 1. Declare accumulator in registers
    float acc[4][32];  // 128 registers per thread!

    // 2. Zero-initialize
    #pragma unroll
    for (int i = 0; i < 4; ++i)
        for (int j = 0; j < 32; ++j)
            acc[i][j] = 0.0f;

